// ChangeDetectorRef: manual control
@Component({ changeDetection: ChangeDetectionStrategy.OnPush, template: `{{ value }}` })
export class ManualComponent implements OnInit {
  value = '';
  constructor(private cdr: ChangeDetectorRef) {}

  ngOnInit() {
    // Third-party callback outside Angular zone
    someExternalLibrary.onData((data: string) => {
      this.value = data;
      this.cdr.markForCheck();  // tell Angular to check this component next tick
    });
  }
}

// NgZone: run heavy computation outside Angular to avoid CD thrashing
@Component({...})
export class ChartComponent implements OnInit {
  constructor(private zone: NgZone) {}

  ngOnInit() {
    this.zone.runOutsideAngular(() => {
      // Runs heavy chart animation loop — no CD triggered per frame
      requestAnimationFrame(() => this.updateChart());
    });
  }

  onDataUpdate(data: ChartData) {
    // Re-enter Angular zone to update template
    this.zone.run(() => {
      this.chartData.set(data);  // signal update triggers targeted CD
    });
  }
}

