// OnPush + signals: the ideal combination
@Component({
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `<p>{{ userName() }} has {{ messageCount() }} messages</p>`
})
export class InboxHeaderComponent {
  userName = input.required<string>();        // signal input
  messageCount = input<number>(0);            // signal input with default
  // OnPush automatically tracks these signal reads — no manual markForCheck needed
}
